use super::*;
use std::collections::BTreeSet;

mod native {
    // Keep the independently audited generated bytes separate from rustfmt's
    // module traversal. This is literal data, not executable reference code.
    include!("../fixtures/m41_native_air_speed_wind.rs");
}

#[test]
fn actual_native_wind_handoff_and_pressure_bits_match_all_component_calls() {
    let mut modes = BTreeSet::new();
    let (mut configurations, mut calls, mut observed, mut suppressed, mut nonzero) =
        (0, 0, 0, 0, 0);
    for &(label, config, rows) in native::CASES {
        configurations += 1;
        modes.insert(config.mode);
        assert_eq!(config.frame_id, "rig/body/air_speed");
        assert_eq!(
            config.topic,
            format!(
                "/m41/native_air_speed_wind/{}/{}",
                config.mode, config.instance
            )
        );
        assert_eq!(
            label,
            if config.mode == "reload" {
                format!("reload/{}", config.instance)
            } else {
                config.mode.to_owned()
            }
        );
        assert_eq!(config.instance, if label == "reload/1" { 1 } else { 0 });
        assert_eq!(
            config.frequency,
            if matches!(config.mode, "rate100" | "active100") {
                100
            } else {
                0
            }
        );
        assert_eq!(config.wind_present, config.mode != "calm-omitted");
        let requested = config.requested_wind.map(f64::from_bits);
        let wind = effective_wind(requested);
        assert!(requested.into_iter().all(f64::is_finite));
        assert_eq!(wind.map(f64::to_bits), config.effective_wind);
        if !config.wind_present {
            assert_eq!(config.requested_wind, [0; 3]);
        }
        let parameters = config.noise.map(f64::from_bits);
        assert!(parameters.into_iter().all(f64::is_finite));
        // This component campaign deliberately contains only deterministic noise.
        assert_eq!(&parameters[1..], &[0.0; 6]);
        let pressure = sdformat::Noise {
            kind: match config.noise_kind {
                "none" => sdformat::NoiseKind::None,
                "gaussian" => sdformat::NoiseKind::Gaussian,
                other => panic!("unreviewed native noise kind: {other}"),
            },
            mean: parameters[0],
            stddev: parameters[1],
            bias_mean: parameters[2],
            bias_stddev: parameters[3],
            dynamic_bias_stddev: parameters[4],
            dynamic_bias_correlation_time: parameters[5],
            precision: parameters[6],
        };
        if config.mode == "reload" {
            assert_eq!(
                config.noise_kind,
                if config.instance == 0 {
                    "none"
                } else {
                    "gaussian"
                }
            );
            assert_eq!(parameters[0], if config.instance == 0 { 0.0 } else { 0.1 });
        }
        let mut noise = PressureNoise::new(&pressure, [41; 32], 7).unwrap();
        let (mut sequence, mut next_time) = (0, 0);
        let times: &[u64] = match config.mode {
            "rate100" => &[1, 2, 9, 10, 11, 20],
            "active100" => &[1, 2, 9, 10, 10, 11, 20],
            _ => &[1, 2, 3, 4, 5],
        };
        assert_eq!(rows.len(), times.len());
        for (index, row) in rows.iter().enumerate() {
            calls += 1;
            assert_eq!(row.index as usize, index);
            assert_eq!(row.time_ns, times[index] * 1_000_000);
            assert_eq!(
                row.active,
                if config.mode == "active100" {
                    [false, true, true, false, true, true, true][index]
                } else {
                    true
                }
            );
            assert!(!row.force);
            assert!(row.has_connections);
            assert_eq!(row.next_before_ns, next_time);
            // These are original Sensors Active/deadline observations, not Scene
            // demand/pause semantics. Production acquisition controls are separate.
            let updated = row.active && (config.frequency == 0 || row.time_ns >= next_time);
            if updated && config.frequency != 0 {
                next_time += 10_000_000;
                if next_time <= row.time_ns {
                    next_time += ((row.time_ns - next_time) / 10_000_000 + 1) * 10_000_000;
                }
            }
            assert_eq!(row.next_after_ns, next_time);
            let pose = row.world_pose.map(f64::from_bits);
            let q = [pose[3], pose[4], pose[5], pose[6]];
            assert!(pose.into_iter().all(f64::is_finite));
            let norm = q[3] * q[3] + q[0] * q[0] + q[1] * q[1] + q[2] * q[2];
            assert!((norm - 1.0).abs() <= 1e-12);
            let velocity = row.velocity_sensor.map(f64::from_bits);
            let relative = relative_air_velocity(velocity, q, wind);
            if wind != [0.0; 3] {
                nonzero += 1;
                assert_eq!(
                    wind_to_sensor(q, wind).map(f64::to_bits),
                    row.native_math_wind_sensor,
                    "{label} call {}",
                    row.index
                );
                assert_eq!(
                    relative.map(f64::to_bits),
                    row.native_math_relative_air,
                    "{label} call {}",
                    row.index
                );
            } else {
                // Native always subtracts a rotated zero. Rust's accepted legacy
                // path bypasses that operation; only final readings must match.
                assert_eq!(relative.map(f64::to_bits), row.velocity_sensor);
            }
            match row.publication {
                native::Publication::Suppressed => {
                    assert!(!updated);
                    suppressed += 1;
                }
                native::Publication::Observed(output) => {
                    assert!(updated);
                    assert_eq!(output.sequence, sequence.to_string());
                    sequence += 1;
                    assert!((1..=8192).contains(&output.header_wire.len()));
                    assert!((1..=8192).contains(&output.wire.len()));
                    let input = AirSpeedInput {
                        world_z: pose[2],
                        velocity_sensor: relative,
                    };
                    let reading = match &mut noise {
                        Some(noise) => noise.apply(input).unwrap(),
                        None => gz_sensors::air_speed::air_speed(input).unwrap(),
                    };
                    assert_eq!(
                        reading.diff_pressure.to_bits(),
                        output.pressure,
                        "{label} call {}",
                        row.index
                    );
                    assert_eq!(
                        reading.temperature.to_bits(),
                        output.temperature,
                        "{label} call {}",
                        row.index
                    );
                    observed += 1;
                }
            }
        }
        assert_eq!(sequence, if config.frequency == 0 { 5 } else { 3 });
    }
    assert_eq!(
        (
            modes.len(),
            configurations,
            calls,
            observed,
            suppressed,
            nonzero
        ),
        (18, 19, 98, 91, 7, 88)
    );
}
